  1	<!--
  2	  AC: @ui-settings-view ac-1 — Displays project config, conventions list, daemon connection info,
  3	  and shadow branch status. Read-only for v1.
  4	-->
  5	<script lang="ts">
  6		import { onMount, onDestroy } from 'svelte';
  7		import {
  8			fetchHealth,
  9			fetchConventions,
 10			fetchProjectConfig,
 11			fetchShadowStatus,
 12			type HealthResponse,
 13			type ConventionItem,
 14			type ProjectConfig,
 15			type ShadowStatus
 16		} from '$lib/api';
 17		import { isStaticMode } from '$lib/stores/mode.svelte';
 18		import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
 19		import { getProjectVersion } from '$lib/stores/project.svelte';
 20		import { Card, CardContent, CardHeader, CardTitle } from '$lib/components/ui/card';
 21		import { Badge } from '$lib/components/ui/badge';
 22		import SettingsIcon from '@lucide/svelte/icons/settings';
 23		import ServerIcon from '@lucide/svelte/icons/server';
 24		import FolderGitIcon from '@lucide/svelte/icons/folder-git-2';
 25		import BookOpenIcon from '@lucide/svelte/icons/book-open';
 26		import PackageIcon from '@lucide/svelte/icons/package';
 27		import CheckCircleIcon from '@lucide/svelte/icons/check-circle';
 28		import XCircleIcon from '@lucide/svelte/icons/x-circle';
 29		import ClockIcon from '@lucide/svelte/icons/clock';
 30		import UsersIcon from '@lucide/svelte/icons/users';
 31		import GitBranchIcon from '@lucide/svelte/icons/git-branch';
 32		import FolderIcon from '@lucide/svelte/icons/folder';
 33		import ChevronDownIcon from '@lucide/svelte/icons/chevron-down';
 34		import ChevronRightIcon from '@lucide/svelte/icons/chevron-right';
 35	
 36		// ── Data state ──
 37		let health = $state<HealthResponse | null>(null);
 38		let conventions = $state<ConventionItem[]>([]);
 39		let projectConfig = $state<ProjectConfig | null>(null);
 40		let shadowStatus = $state<ShadowStatus | null>(null);
 41		let loading = $state(true);
 42		let error = $state('');
 43	
 44		// ── Convention expand state ──
 45		let expandedConventions = $state<Set<string>>(new Set());
 46	
 47		// ── Lifecycle ──
 48		onMount(async () => {
 49			await loadData();
 50	
 51			if (!isStaticMode()) {
 52				subscribe(['files:updates']);
 53				on('files:updates', handleUpdate);
 54			}
 55		});
 56	
 57		onDestroy(() => {
 58			if (!isStaticMode()) {
 59				off('files:updates', handleUpdate);
 60				unsubscribe(['files:updates']);
 61			}
 62		});
 63	
 64		// Reload on project change
 65		$effect(() => {
 66			const version = getProjectVersion();
 67			if (version > 0) {
 68				loadData();
 69			}
 70		});
 71	
 72		// ── Data loading ──
 73		async function loadData() {
 74			try {
 75				loading = true;
 76				error = '';
 77	
 78				const results = await Promise.allSettled([
 79					fetchHealth(),
 80					fetchConventions(),
 81					fetchProjectConfig(),
 82					fetchShadowStatus()
 83				]);
 84	
 85				// Health
 86				if (results[0].status === 'fulfilled') {
 87					health = results[0].value;
 88				}
 89	
 90				// Conventions
 91				if (results[1].status === 'fulfilled') {
 92					conventions = results[1].value.items;
 93				}
 94	
 95				// Project config
 96				if (results[2].status === 'fulfilled') {
 97					projectConfig = results[2].value;
 98				}
 99	
100				// Shadow status
101				if (results[3].status === 'fulfilled') {
102					shadowStatus = results[3].value;
103				}
104	
105				// Only show error if all requests failed
106				const allFailed = results.every((r) => r.status === 'rejected');
107				if (allFailed) {
108					const firstErr = results[0].status === 'rejected' ? results[0].reason : null;
109					error = firstErr instanceof Error ? firstErr.message : 'Failed to load settings';
110				}
111			} catch (err) {
112				error = err instanceof Error ? err.message : 'Failed to load settings';
113			} finally {
114				loading = false;
115			}
116		}
117	
118		function handleUpdate() {
119			loadData();
120		}
121	
122		// ── Formatting helpers ──
123		function formatUptime(seconds: number): string {
124			const days = Math.floor(seconds / 86400);
125			const hours = Math.floor((seconds % 86400) / 3600);
126			const minutes = Math.floor((seconds % 3600) / 60);
127			const secs = Math.floor(seconds % 60);
128	
129			const parts: string[] = [];
130			if (days > 0) parts.push(`${days}d`);
131			if (hours > 0) parts.push(`${hours}h`);
132			if (minutes > 0) parts.push(`${minutes}m`);
133			parts.push(`${secs}s`);
134			return parts.join(' ');
135		}
136	
137		function toggleConvention(domain: string) {
138			const next = new Set(expandedConventions);
139			if (next.has(domain)) {
140				next.delete(domain);
141			} else {
142				next.add(domain);
143			}
144			expandedConventions = next;
145		}
146	</script>
147	
148	<div class="flex flex-col gap-6 p-6">
149		<!-- Header -->
150		<div>
151			<h1 class="text-2xl font-bold">Settings</h1>
152			<p class="text-sm text-muted-foreground">
153				Project configuration, conventions, and daemon status
154			</p>
155		</div>
156	
157		{#if error}
158			<div
159				class="bg-destructive/10 text-destructive rounded-lg p-4 text-sm"
160				data-testid="settings-error"
161				role="alert"
162			>
163				{error}
164			</div>
165		{/if}
166	
167		{#if loading}
168			<!-- AC: @ui-settings-view ac-1 — Loading skeleton -->
169			<div class="flex flex-col gap-4" data-testid="settings-loading">
170				{#each Array(4) as _}
171					<div class="h-40 rounded-lg bg-muted ds-shimmer"></div>
172				{/each}
173			</div>
174		{:else}
175			<!-- AC: @ui-settings-view ac-1 — Project config section -->
176			<Card data-testid="settings-project-config">
177				<CardHeader>
178					<CardTitle class="flex items-center gap-2 text-base">
179						<PackageIcon class="size-4" />
180						Project Configuration
181					</CardTitle>
182				</CardHeader>
183				<CardContent class="pt-0">
184					{#if projectConfig?.project}
185						<div class="grid gap-3 sm:grid-cols-2">
186							<div class="flex flex-col gap-1">
187								<span class="text-xs font-medium tracking-wider text-muted-foreground uppercase"
188									>Name</span
189								>
190								<span class="text-sm font-medium" data-testid="project-name">
191									{projectConfig.project.name}
192								</span>
193							</div>
194							<div class="flex flex-col gap-1">
195								<span class="text-xs font-medium tracking-wider text-muted-foreground uppercase"
196									>Version</span
197								>
198								<span class="text-sm font-mono" data-testid="project-version">
199									{projectConfig.project.version}
200								</span>
201							</div>
202							{#if projectConfig.project.status}
203								<div class="flex flex-col gap-1">
204									<span class="text-xs font-medium tracking-wider text-muted-foreground uppercase"
205										>Status</span
206									>
207									<span data-testid="project-status">
208										<Badge variant="secondary">{projectConfig.project.status}</Badge>
209									</span>
210								</div>
211							{/if}
212							{#if projectConfig.kynetic}
213								<div class="flex flex-col gap-1">
214									<span class="text-xs font-medium tracking-wider text-muted-foreground uppercase"
215										>Spec Version</span
216									>
217									<span class="text-sm font-mono" data-testid="spec-version">
218										{projectConfig.kynetic}
219									</span>
220								</div>
221							{/if}
222						</div>
223						{#if projectConfig.rootDir}
224							<div class="mt-4 flex items-center gap-2 border-t pt-3 text-xs text-muted-foreground">
225								<FolderIcon class="size-3" />
226								<code class="rounded bg-muted px-1 py-0.5" data-testid="project-root">
227									{projectConfig.rootDir}
228								</code>
229							</div>
230						{/if}
231					{:else}
232						<div
233							class="flex flex-col items-center justify-center py-8"
234							data-testid="project-config-empty"
235						>
236							<PackageIcon class="mb-2 size-8 text-muted-foreground/30" />
237							<p class="text-sm text-muted-foreground">No project manifest found</p>
238							<p class="text-xs text-muted-foreground">
239								Run <code class="rounded bg-muted px-1 py-0.5">kspec init</code> to create one.
240							</p>
241						</div>
242					{/if}
243				</CardContent>
244			</Card>
245	
246			<!-- AC: @ui-settings-view ac-1 — Daemon connection info section -->
247			<Card data-testid="settings-daemon">
248				<CardHeader>
249					<CardTitle class="flex items-center gap-2 text-base">
250						<ServerIcon class="size-4" />
251						Daemon Connection
252					</CardTitle>
253				</CardHeader>
254				<CardContent class="pt-0">
255					{#if health}
256						<div class="grid gap-3 sm:grid-cols-2">
257							<div class="flex flex-col gap-1">
258								<span class="text-xs font-medium tracking-wider text-muted-foreground uppercase"
259									>Status</span
260								>

