  1	/**
  2	 * Meta API Routes
  3	 *
  4	 * REST endpoints for meta operations:
  5	 * - GET /api/meta/session - get session context
  6	 * - GET /api/meta/agents - list agents
  7	 * - GET /api/meta/workflows - list workflows
  8	 * - GET /api/meta/observations - list observations with filter
  9	 * - GET /api/meta/conventions - list conventions
 10	 * - GET /api/meta/config - get project config
 11	 * - GET /api/meta/shadow - get shadow branch status
 12	 *
 13	 * AC Coverage:
 14	 * - ac-15: GET /api/meta/session returns session context
 15	 * - ac-16: GET /api/meta/agents returns all agents
 16	 * - ac-17: GET /api/meta/workflows returns all workflows
 17	 * - ac-18: GET /api/meta/observations with filter
 18	 * - @ui-settings-view ac-1: conventions, config, shadow status endpoints
 19	 */
 20	
 21	import { Elysia, t } from 'elysia';
 22	import {
 23	  initContext,
 24	  loadMetaContext,
 25	  loadSessionContext,
 26	} from '../../parser/index.js';
 27	
 28	interface MetaRouteOptions {}
 29	
 30	export function createMetaRoutes(options: MetaRouteOptions = {}) {
 31	  // No closure-scoped kspecDir needed - comes from middleware
 32	
 33	  return new Elysia({ prefix: '/api/meta' })
 34	    // AC: @api-contract ac-15 - Get session context
 35	    .get('/session', async ({ projectContext }) => {
 36	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 37	      const ctx = await initContext(projectContext.path);
 38	      const session = await loadSessionContext(ctx);
 39	
 40	      // AC: @api-contract ac-15 - Return session context (focus, threads, questions)
 41	      return {
 42	        focus: session.focus,
 43	        threads: session.threads || [],
 44	        questions: session.questions || [],
 45	        updated_at: session.updated_at,
 46	      };
 47	    })
 48	
 49	    // AC: @api-contract ac-16 - List agents
 50	    .get('/agents', async ({ projectContext }) => {
 51	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 52	      const ctx = await initContext(projectContext.path);
 53	      const meta = await loadMetaContext(ctx);
 54	
 55	      // AC: @api-contract ac-16 - Return all defined agents
 56	      const agents = meta.agents;
 57	
 58	      return {
 59	        items: agents,
 60	        total: agents.length,
 61	      };
 62	    })
 63	
 64	    // AC: @api-contract ac-17 - List workflows
 65	    .get('/workflows', async ({ projectContext }) => {
 66	      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 67	      const ctx = await initContext(projectContext.path);
 68	      const meta = await loadMetaContext(ctx);
 69	
 70	      // AC: @api-contract ac-17 - Return all defined workflows
 71	      const workflows = meta.workflows;
 72	
 73	      return {
 74	        items: workflows,
 75	        total: workflows.length,
 76	      };
 77	    })
 78	
 79	    // AC: @api-contract ac-18 - List observations with filter
 80	    .get(
 81	      '/observations',
 82	      async ({ query, projectContext }) => {
 83	        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 84	        const ctx = await initContext(projectContext.path);
 85	        const meta = await loadMetaContext(ctx);
 86	
 87	        // Start with all observations
 88	        let filtered = meta.observations || [];
 89	
 90	        // AC: @api-contract ac-18 - Filter by resolved status
 91	        if (query.resolved !== undefined) {
 92	          const resolvedFilter = query.resolved === 'true';
 93	          filtered = filtered.filter((obs) => {
 94	            const isResolved = !!obs.resolved_at;
 95	            return isResolved === resolvedFilter;
 96	          });
 97	        }
 98	
 99	        // Optional type filter (not in ACs but useful)
100	        if (query.type) {
101	          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
102	          filtered = filtered.filter((obs) => typeFilters.includes(obs.type));
103	        }
104	
105	        // Sort by created_at descending (newest first)
106	        const sorted = [...filtered].sort(
107	          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
108	        );
109	
110	        return {
111	          items: sorted,
112	          total: sorted.length,
113	        };
114	      },
115	      {
116	        query: t.Object({
117	          resolved: t.Optional(t.String()),
118	          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
119	        }),
120	      }
121	    )
122	
123	    // AC: @ui-settings-view ac-1 - List conventions
124	    .get('/conventions', async ({ projectContext }) => {
125	      const ctx = await initContext(projectContext.path);
126	      const meta = await loadMetaContext(ctx);
127	
128	      const conventions = meta.conventions;
129	
130	      return {
131	        items: conventions,
132	        total: conventions.length,
133	      };
134	    })
135	
136	    // AC: @ui-settings-view ac-1 - Get project config
137	    .get('/config', async ({ projectContext }) => {
138	      const ctx = await initContext(projectContext.path);
139	
140	      return {
141	        project: ctx.manifest?.project ?? null,
142	        kynetic: ctx.manifest?.kynetic ?? null,
143	        manifestPath: ctx.manifestPath,
144	        specDir: ctx.specDir,
145	        rootDir: ctx.rootDir,
146	      };
147	    })
148	
149	    // AC: @ui-settings-view ac-1 - Get shadow branch status
150	    .get('/shadow', async ({ projectContext }) => {
151	      const ctx = await initContext(projectContext.path);
152	
153	      if (!ctx.shadow) {
154	        return {
155	          enabled: false,
156	          branchName: null,
157	          worktreeDir: null,
158	          projectRoot: null,
159	        };
160	      }
161	
162	      return {
163	        enabled: ctx.shadow.enabled,
164	        branchName: ctx.shadow.branchName,
165	        worktreeDir: ctx.shadow.worktreeDir,
166	        projectRoot: ctx.shadow.projectRoot,
167	      };
168	    });
169	}

