  2	 * Type validation tests for @kynetic-ai/shared package
  3	 *
  4	 * Verifies:
  5	 * 1. Types compile correctly
  6	 * 2. Exports are accessible
  7	 * 3. Type definitions match expected structure
  8	 *
  9	 * Uses vitest expectTypeOf for compile-time type checking.
 10	 */
 11	
 12	import { describe, it, expectTypeOf } from 'vitest';
 13	import type {
 14	  // Core schemas
 15	  TaskStatus,
 16	  TaskType,
 17	  ItemType,
 18	  ImplementationStatus,
 19	  Maturity,
 20	  ObservationType,
 21	  // API types
 22	  PaginatedResponse,
 23	  ErrorResponse,
 24	  TaskSummary,
 25	  TaskDetail,
 26	  Note,
 27	  Todo,
 28	  ItemSummary,
 29	  ItemDetail,
 30	  AcceptanceCriterion,
 31	  InboxItem,
 32	  SessionContext,
 33	  Agent,
 34	  Workflow,
